LIVE.enMeas = () => {const f = energyFinal(S), dayF = 1440 / Math.max(60, S.t), cost = c => (S.en.cost[c] || 0) * dayF * 365 / S.cfg.fx;
  const rows = MEASURES.map(m => {let base, save;
    if (m.basis == 'diesel') {base = S.en.dieselAirportL * dayF * 365 * S.cfg.dieselEgpL / S.cfg.fx; save = base * m.pct / 100 - S.en.dieselAirportL * dayF * 365 * m.pct / 100 * 3 * S.cfg.elec.offpeakEgp / S.cfg.fx}
    else if (m.basis == 'pv') {base = Object.values(S.en.cost).reduce((a, b) => a + b, 0) * dayF * 365 / S.cfg.fx; save = 8000 * 5.3 * 365 * S.cfg.elec.offpeakEgp * .97 / S.cfg.fx}
    else if (m.basis == 'conv') {base = cost('conv'); save = base * (1 - Math.min(1, (S.bagAct ? .6 : .6))) * m.pct / 100}
    else {base = cost(m.basis); save = base * m.pct / 100}
    return [m, base, save, save > 0 ? m.capexUsd / save : Infinity]});
  return `<table><tr><th>Measure</th><th class="n">Annualised baseline cost</th><th class="n">Est. saving %</th><th class="n">Est. annual saving</th><th class="n">Capex</th><th class="n">Simple payback</th><th>Operational impact</th></tr>${rows.map(([m, b, s, pb]) => `<tr><td>${m.name}</td><td class="n">${money(b)}</td><td class="n">${m.basis == 'pv' ? '8 MWp × 5.3 kWh/kWp·d' : m.pct + '%'}</td><td class="n pos">${money(s)}</td><td class="n">${money(m.capexUsd)}</td><td class="n">${isFinite(pb) ? pb.toFixed(1) + ' yr' : '—'}</td><td class="mu sm">${m.impact}</td></tr>`).join('')}</table>
  <p class="note">Run-rate = today's simulated consumption × (1440 / elapsed minutes) × 365, at configured tariffs. Payback = capex ÷ annual saving; excludes financing, maintenance changes and tariff escalation. Insufficient assumptions → treat as screening estimates.</p>`};
