async function dl(name, txt, type) {
  const d = window.claude && window.claude.use ? await window.claude.use('downloads').catch(() => null) : null;
  if (d) {try {await d.save({filename: name, data: txt})} catch (e) {if (e && e.code != 'declined') alert('Download unavailable here: ' + (e.message || e.code))} return}
  const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([txt], {type})); a.download = name; a.click()
}
