const termOf = r => {const t = STAND[r.stand].term; return TERMS.includes(t) ? t : TERMS.includes(r.term) ? r.term : 'T2'};
function termFlow(T) { // same occupancy model as the engine, split by process stage
  const f = {'Check-in & bag drop': 0, 'Security': 0, 'Airside & gates': 0, 'Arrivals: immigration & reclaim': 0};
  for (const r of S.R) {if (termOf(r) != T) continue;
    if (r.dep && r.offBlk == null && !r.dep.cancelled) {const tb = r.tobt ?? r.dep.std, n = r.paxOut * clamp((S.t - (r.dep.std - 180)) / 140, 0, 1) * (1 - clamp((S.t - (tb - 35)) / 30, 0, 1)), dt = tb - S.t;
      f[dt > 100 ? 'Check-in & bag drop' : dt > 70 ? 'Security' : 'Airside & gates'] += n}
    if (r.arr && r.onBlk != null && S.t - r.onBlk < 40) f['Arrivals: immigration & reclaim'] += r.paxIn * (1 - (S.t - r.onBlk) / 40)}
  return f;
}
VIEWS['pax.term'] = {sub: 'Terminal detail: passengers, flights, gates, services and energy (simulated; images illustrative).',
  html: () => {const T = curTerm, z = ZONE[T];
    return `<div class="row" style="margin-bottom:10px"><button class="btn" onclick="go('pax','services')">‹ All terminals</button><div class="seg">${TERMS.map(t => `<button class="${t == T ? 'on' : ''}" onclick="openTerm('${t}')">${ZONE[t].name}</button>`).join('')}</div></div>
  <div class="g" style="grid-template-columns:minmax(0,340px) minmax(0,1fr)"><div class="card" style="padding:0;overflow:hidden"><div style="height:200px;background:url(${IMG[TIMG[T]]}) center/cover;position:relative"><span class="tag" style="position:absolute;left:8px;bottom:8px;background:#000a;color:#fff">illustrative image</span></div>
    <div style="padding:12px"><div class="ch">${z.name}</div><div data-live="termRes"></div></div></div>
    <div class="g" style="align-content:start"><div class="kp" data-live="termKpi"></div><div class="g g2"><div class="card"><div class="ch">Where passengers are now<span class="sp"></span><span class="tag">simulated</span></div><div data-live="termFlowTab"></div></div>
      <div class="card"><div class="ch">Passengers in terminal today</div><div data-live="termChart"></div></div></div></div></div>
  <div class="g g2" style="margin-top:12px"><div class="card"><div class="ch">Departures</div><div data-live="termDep" class="tw" style="max-height:340px"></div></div><div class="card"><div class="ch">Arrivals</div><div data-live="termArr" class="tw" style="max-height:340px"></div></div></div>
  <div class="g g3" style="margin-top:12px"><div class="card"><div class="ch">Gates & stands</div><div data-live="termStands" class="tw" style="max-height:340px"></div></div><div class="card"><div class="ch">Passenger care & services</div><div data-live="termCare"></div></div><div class="card"><div class="ch">Energy today</div><div data-live="termEnergy"></div></div></div>`}};
LIVE.termKpi = () => {const T = curTerm, dep = S.R.filter(r => r.dep && termOf(r) == T), arr = S.R.filter(r => r.arr && termOf(r) == T), q = queueMin(T);
  const nd = dep.filter(r => r.offBlk == null && !r.dep.cancelled && (r.tobt ?? r.dep.std) < S.t + 120).length, na = arr.filter(r => r.onBlk == null && !r.diverted && r.eta < S.t + 120).length;
  const gone = dep.filter(r => r.offBlk != null && r.offBlk >= 0), dly = gone.length ? Math.round(gone.reduce((a, r) => a + Math.max(0, r.offBlk - r.dep.std), 0) / gone.length) : 0;
  const late = dep.filter(r => r.offBlk == null && !r.dep.cancelled && S.t > r.dep.std + 15).length, paxT = gone.reduce((a, r) => a + r.paxOut, 0) + arr.filter(r => r.onBlk != null && r.onBlk >= 0 && r.onBlk <= S.t).reduce((a, r) => a + r.paxIn, 0);
  return kpiTile('Passengers now', Math.round(S.occ[T] || 0).toLocaleString()) + kpiTile('Security queue', q + ' min', TRES[T].sec + ' lanes', '', q > 20 ? 'neg' : '') + kpiTile('Departures next 2 h', nd) + kpiTile('Arrivals next 2 h', na) +
    kpiTile('Avg departure delay', dly + ' min', gone.length + ' departed', '', dly > 15 ? 'neg' : '') + kpiTile('Late, not off-block', late, 'over 15 min past STD', '', late ? 'neg' : '') + kpiTile('Passengers handled', paxT.toLocaleString(), 'today so far')};
LIVE.termFlowTab = () => {const f = termFlow(curTerm), tot = Object.values(f).reduce((a, b) => a + b, 0) || 1;
  return Object.entries(f).map(([k, v], i) => `<div style="margin:7px 0"><div class="row sm"><span>${k}</span><span class="sp"></span><b>${Math.round(v).toLocaleString()}</b><span class="mu" style="width:34px;text-align:right">${Math.round(100 * v / tot)}%</span></div><div style="height:8px;border-radius:4px;background:var(--grid);overflow:hidden;margin-top:3px"><div style="height:100%;width:${(100 * v / tot).toFixed(1)}%;background:var(--s${i + 1});border-radius:4px"></div></div></div>`).join('') + '<p class="mu sm" style="margin:8px 0 0">Stage estimated from each flight\'s time to departure (check-in > 100 min, security 70–100 min, then airside). Arrivals counted for 40 min after on-block.</p>'};
LIVE.termChart = () => {const T = curTerm, pts = S.snap.filter(x => x.occ && x.t <= S.t).map(x => [x.t, Math.round(x.occ[T] || 0)]); pts.push([S.t, Math.round(S.occ[T] || 0)]);
  return lineChart('c-term', [{name: 'Passengers in ' + ZONE[T].name, color: 'var(--s1)', pts}], {fx: loc, fy: v => kfmt(Math.round(v))})};
const termRow = (r, d) => {const f = d ? r.dep.fl : r.arr.fl, sch = d ? r.dep.std : r.arr.sta, est = d ? projOff(r) ?? sch : r.onBlk ?? r.eta, dl = Math.max(0, Math.round(est - sch)), bags = d ? rbags(S, r.id).filter(b => b.r == r.id && !b.arr) : [];
  return `<tr class="r" onclick="inspect('rot','${r.id}')"><td><b>${f}</b></td><td>${d ? r.dep.apt : r.arr.apt}</td><td>${loc(sch)}</td><td class="${dl > 15 ? 'neg' : ''}">${est != null ? loc(est) : '—'}</td><td>${r.stand}${STAND[r.stand].kind == 'contact' ? '' : ' <span class="mu sm">bus</span>'}</td><td class="n">${d ? r.paxOut : r.paxIn}</td>${d ? `<td class="n">${bags.filter(b => b.st == 'LOADED' || b.st == 'IN FLIGHT').length}/${bags.length}</td>` : ''}<td>${d && r.dep.cancelled ? bd('CANCELLED', 'cr') : bd(r.ph, phCls(r))}</td></tr>`};
LIVE.termDep = () => {const l = S.R.filter(r => r.dep && termOf(r) == curTerm && r.dep.std < DAY_END + 60).sort((a, b) => (a.offBlk != null) - (b.offBlk != null) || a.dep.std - b.dep.std);
  return l.length ? `<table><tr><th>Flight</th><th>To</th><th>STD</th><th>Est / actual</th><th>Gate</th><th class="n">Pax</th><th class="n">Bags loaded</th><th>Status</th></tr>${l.map(r => termRow(r, 1)).join('')}</table>` : '<div class="empty">No departures</div>'};
LIVE.termArr = () => {const l = S.R.filter(r => r.arr && termOf(r) == curTerm).sort((a, b) => (a.onBlk != null && a.onBlk <= S.t) - (b.onBlk != null && b.onBlk <= S.t) || a.arr.sta - b.arr.sta);
  return l.length ? `<table><tr><th>Flight</th><th>From</th><th>STA</th><th>Est / actual</th><th>Gate</th><th class="n">Pax</th><th>Status</th></tr>${l.map(r => termRow(r, 0)).join('')}</table>` : '<div class="empty">No arrivals</div>'};
LIVE.termStands = () => {const st = STANDS.filter(s => s.term == curTerm || (curTerm == 'STC' && s.kind == 'stc'));
  return `<table><tr><th>Stand</th><th>Type</th><th>Occupant</th><th>Status</th></tr>${st.map(s => {const o = S.rot[S.stOcc[s.id]];
    return `<tr class="r" onclick="inspect('stand','${s.id}')"><td><b>${s.id}</b></td><td class="sm">${s.kind == 'contact' ? 'bridge' : s.kind} · code ${s.max}</td><td>${o ? fid(o) + ' <span class="mu sm">' + o.type + '</span>' : '—'}</td><td>${S.stClosed[s.id] ? bd('MAINTENANCE', 'wn') : o ? bd(o.ph, phCls(o)) : S.stRes[s.id] ? bd('RESERVED', 'vi') : bd('FREE', 'ok')}</td></tr>`}).join('')}</table>`};
LIVE.termRes = () => {const T = curTerm, R = TRES[T], pbb = STANDS.filter(s => s.term == T && s.kind == 'contact'), pbbUse = pbb.filter(s => S.stOcc[s.id]).length, pm = S.pm.filter(p => p.kind == 'stand' && STAND[p.ref] && STAND[p.ref].term == T && p.st != 'DONE');
  return `<div class="kv"><span>Check-in counters</span><b>${R.ci}</b><span>Security lanes</span><b>${R.sec}</b><span>Immigration booths</span><b>${R.imm}</b><span>Boarding bridges in use</span><b>${pbbUse} / ${pbb.length}</b><span>Est. security wait</span><b>${queueMin(T)} min</b>${pm.length ? `<span>Planned stand maintenance</span><b>${pm.map(p => p.ref + ' ' + loc(p.start)).join(', ')}</b>` : ''}</div><p class="mu sm" style="margin:8px 0 0">Counter, lane and booth counts are illustrative.</p>`};
LIVE.termCare = () => {const T = curTerm, mine = S.R.filter(r => r.dep && termOf(r) == T), l = mine.filter(r => r.offBlk == null && !r.dep.cancelled && S.t - r.dep.std > 60), c = mine.filter(r => r.dep.cancelled), fl = new Set(mine.map(r => r.dep.fl)), cl = S.claims.filter(x => fl.has(x.fl));
  return `${l.length || c.length ? `<table><tr><th>Flight</th><th class="n">Pax</th><th>Delay</th><th>Care (airline duty)</th></tr>${l.map(r => `<tr class="r" onclick="inspect('rot','${r.id}')"><td>${r.dep.fl}</td><td class="n">${r.paxOut}</td><td>${S.t - r.dep.std} min</td><td class="sm">${S.t - r.dep.std > 180 ? 'Meals + rebooking' : 'Refreshments'}</td></tr>`).join('')}${c.map(r => `<tr class="r" onclick="inspect('rot','${r.id}')"><td>${r.dep.fl}</td><td class="n">${r.paxOut}</td><td>cancelled</td><td class="sm">Rebooking + hotel</td></tr>`).join('')}</table>` : '<div class="mu sm">No long delays needing passenger care.</div>'}
  <div class="kv" style="margin-top:10px"><span>Mishandled-bag reports</span><b>${cl.length}</b><span>Reduced-mobility assists (est.)</span><b>${Math.round((S.occ[T] || 0) * .006)} in progress</b></div><div class="row" style="margin-top:10px"><button class="btn" onclick="go('pax','claims')">Bag claims</button><button class="btn" onclick="go('pax','tickets')">Tickets & refunds</button></div>`};
LIVE.termEnergy = () => {const k = Object.entries(S.en.kwhT[curTerm] || {}), tot = k.reduce((a, [, v]) => a + v, 0);
  return k.length ? `<table>${k.sort((a, b) => b[1] - a[1]).map(([c, v]) => `<tr><td>${ENCATS[c]}</td><td class="n">${kfmt(v)} kWh</td><td class="n mu">${Math.round(100 * v / (tot || 1))}%</td></tr>`).join('')}<tr><td><b>Total</b></td><td class="n"><b>${kfmt(tot)} kWh</b></td><td></td></tr></table><div class="row" style="margin-top:10px"><button class="btn" onclick="go('biz','energy')">Energy management</button></div>` : '<div class="empty">No metered data yet</div>'};
LIVE.paxCare = () => {const l = S.R.filter(r => r.dep && r.offBlk == null && r.tobt != null && S.t - r.dep.std > 60 && !r.dep.cancelled); const c = S.R.filter(r => r.dep && r.dep.cancelled);
  return (l.length || c.length) ? `<table><tr><th>Flight</th><th>Pax</th><th>Delay</th><th>Care due (airline obligation, illustrative)</th></tr>${l.map(r => `<tr><td>${r.dep.fl}</td><td>${r.paxOut}</td><td>${S.t - r.dep.std} min</td><td>${S.t - r.dep.std > 180 ? 'Meals + rebooking options' : 'Refreshments'}</td></tr>`).join('')}${c.map(r => `<tr><td>${r.dep.fl}</td><td>${r.paxOut}</td><td>cancelled</td><td>Rebooking + accommodation</td></tr>`).join('')}</table>` : '<div class="empty">No long delays requiring passenger care</div>'};
VIEWS['pax.tickets'] = {sub: 'Booking cancellation & refund calculator (illustrative fare rules, EGP). No payment data is collected.',
  html: () => `<div class="card"><div class="row"><select id="fam"><option>Saver</option><option>Flex</option><option>Premium</option></select><select id="ns"><option value="0">Cancel before departure</option><option value="1">No-show</option></select><button class="btn pri" onclick="cancelTk()">Cancel & calculate</button></div><div data-live="tkList" style="margin-top:10px"></div></div>`};
LIVE.tkList = () => S.tk.map(x => `<div class="al info" style="cursor:default">${x}</div>`).join('') || '<div class="empty">No cancellations yet.</div>';
function cancelTk() {if (!can()) return; const F = {Saver: [4200, 1, 'Non-refundable fare family (illustrative)'], Flex: [6800, .15, '15% change/cancel deduction (illustrative)'], Premium: [12500, 0, 'Fully refundable (illustrative)']}, k = $('#fam').value, ns = $('#ns').value == '1', [p, fee, w] = F[k], ded = ns ? p : p * fee;
  S.tk.unshift(`<b>${k}</b> original EGP ${p} · deduction EGP ${ded} · <b>refund EGP ${p - ded}</b><br><span class="mu">${ns ? 'No-show forfeits fare (illustrative rule)' : w}</span>`); ev(S, 'PassengerBookingCancelled', 'TKT', 'Fare ' + k); audit('Ticket cancel ' + k); live(true)}
VIEWS['pax.claims'] = {sub: 'Mishandled baggage (PIR) generated by missed loads, BHS failures and missed connections.', html: () => `<div class="card"><div data-live="claimTab" class="tw"></div></div>`};
const CLST = ['OPEN', 'LOCATED', 'FORWARDED', 'DELIVERED', 'CLOSED'];
LIVE.claimTab = () => S.claims.length ? `<table><tr><th>PIR</th><th>Time</th><th>Bag</th><th>Passenger</th><th>Flight</th><th>Cause</th><th class="n">Est. cost</th><th>Bearer</th><th>Recovery</th><th>Status</th><th></th></tr>${S.claims.slice().reverse().map(c => `<tr><td>${c.id}</td><td>${loc(c.t)}</td><td><a href="#" style="color:var(--ac)" onclick="inspect('bag','${c.bag}');return false">${c.bag}</a></td><td>${c.px}</td><td>${c.fl}</td><td>${c.cause}</td><td class="n">${money(c.usd)}</td><td>${c.bearer}</td><td>${c.recover ? c.recover + '% from airport (BHS contract)' : '—'}</td><td>${bd(c.st, c.st == 'CLOSED' ? 'ok' : 'wn')}</td><td>${c.st != 'CLOSED' ? `<button class="btn" onclick="if(can()){const c=S.claims.find(x=>x.id=='${c.id}');c.st=CLST[CLST.indexOf(c.st)+1];audit('Claim ${c.id} → '+c.st);live(true)}">Advance</button>` : ''}</td></tr>`).join('')}</table>` : '<div class="empty">No mishandled bags. Inject “BHS sorter failure” to see claims generated.</div>';
VIEWS['pax.private'] = {sub: 'General aviation (FBO) and the seasonal terminal (charters).', html: () => `<div class="g g2"><div class="card"><div class="ch">Private aviation / FBO</div><div data-live="gaTab"></div></div><div class="card"><div class="ch">Seasonal terminal — charter operations</div><div data-live="stcTab"></div></div></div>`};
const opTab = op => `<table><tr><th>Flight</th><th>Type</th><th>Stand</th><th>Arr</th><th>Dep</th><th>Status</th><th class="n">Charges</th></tr>${S.R.filter(r => r.op == op).map(r => `<tr class="r" onclick="inspect('rot','${r.id}')"><td>${fid(r)}</td><td>${r.type}</td><td>${r.stand}</td><td>${loc(r.arr.sta)}</td><td>${r.dep ? loc(r.dep.std) : '—'}</td><td>${bd(r.ph, phCls(r))}</td><td class="n">${money(S.L.filter(e => e.rot == r.id && e.payee == 'Airport' && e.status != 'waived').reduce((a, e) => a + e.usd, 0))}</td></tr>`).join('')}</table>`;
LIVE.gaTab = () => opTab('private') + `<p class="note">Private: landing ×${S.cfg.landing.mult.private}, free parking ${S.cfg.parking.freeMin.private} min, FBO fee $${S.cfg.fbo.usd} paid on departure.</p>`;
LIVE.stcTab = () => opTab('charter') + `<p class="note">Seasonal terminal open (simulated pilgrimage season). Charter landing ×${S.cfg.landing.mult.charter}; cash terms.</p>`;

// ---------- SAFETY & REPORTS ----------
VIEWS['saf.emerg'] = {sub: 'Emergency diversion & unexpected arrival management. Acceptance and safety decisions are never driven by profitability.',
  html: () => `<div class="g g2"><div class="card"><div class="ch">New diversion / emergency request</div><div class="frm">
  <label>Flight ID<input id="dv-fl" value="SV 9917"></label><label>Aircraft type<select id="dv-type">${Object.keys(AC_TYPES).map(t => `<option ${t == 'B77W' ? 'selected' : ''}>${t}</option>`).join('')}</select></label><label>Registration<input id="dv-reg" value="HZ-AK42"></label><label>Operator<input id="dv-op" value="Saudia (diverted)"></label>
  <label>Origin<input id="dv-org" value="JED"></label><label>Intended destination<input id="dv-dst" value="LHR"></label><label>Reason<select id="dv-rsn">${['Medical emergency', 'Technical: hydraulic caution', 'Weather at destination', 'Fuel', 'Disruptive passenger', 'Security'].map(x => `<option>${x}</option>`).join('')}</select></label><label>ETA (min from now)<input id="dv-eta" type="number" value="18"></label>
  <label>Passengers<input id="dv-pax" type="number" value="330"></label><label>Crew<input id="dv-crew" type="number" value="16"></label>
  <label class="ck"><input type="checkbox" id="dv-arff" checked>ARFF standby</label><label class="ck"><input type="checkbox" id="dv-med" checked>Medical team</label><label class="ck"><input type="checkbox" id="dv-fuel" checked>Fuel uplift</label><label class="ck"><input type="checkbox" id="dv-tech">Technical issue reported</label><label class="ck"><input type="checkbox" id="dv-on">Unplanned overnight</label></div>
  <div class="row" style="margin-top:10px"><button class="btn pri" onclick="submitDiv()">Submit request</button><span class="mu sm">Financial treatment: <b>${S.cfg.diversion.treatment}</b> (Tariffs)</span></div></div>
  <div class="card"><div class="ch">Requests</div><div data-live="divList"></div></div></div>`};
function submitDiv() {if (!can()) return; const v = id => $('#' + id).value, c = id => $('#' + id).checked; const reason = v('dv-rsn');
  const d = newDiversion(S, {fl: v('dv-fl'), type: v('dv-type'), reg: v('dv-reg'), op: v('dv-op'), origin: v('dv-org'), dest: v('dv-dst'), reason, etaMin: +v('dv-eta'), pax: +v('dv-pax'), crew: +v('dv-crew'), tech: c('dv-tech') || /Technical/.test(reason), techType: 'HYD', overnight: c('dv-on'), svc: {arff: c('dv-arff'), medical: c('dv-med') || /Medical/.test(reason), fuel: c('dv-fuel')}});
  audit('Diversion request ' + d.fl); live(true)}
LIVE.divList = () => S.div.length ? S.div.slice().reverse().map(d => {
  if (d.status == 'REQUESTED') {const a = assessDiversion(S, d);
    return `<div class="card" style="margin-bottom:10px;border-color:var(--cr)"><div class="ch"><span style="color:var(--tx);text-transform:none;font-size:13px">${d.fl} · ${d.type} · ${esc(d.reason)}</span><span class="sp"></span>${bd('AWAITING DECISION', 'cr')}</div>
    <div class="kv"><span>ETA</span><b>${loc(d.etaT)} (${d.etaT - S.t} min)</b><span>Route</span><b>${d.origin == 'CAI' ? 'CAI departure → returning to CAI' : d.drillOf ? 'Drill — inbound emergency' : d.origin + ' → ' + d.dest + ' (diverting to CAI)'}</b><span>Arrival runway</span><b>${a.rw ? 'RWY ' + a.rw + ' open' : 'NONE OPEN'}</b><span>Traffic within ±5 min</span><b>${a.conflicts.join(', ') || 'none'} — priority sequencing</b><span>Services available</span><b>${Object.entries(a.svc).map(([k, v]) => k + ' ' + v).join(' · ')}</b><span>Requested</span><b>${[d.svc.arff && 'ARFF', d.svc.medical && 'medical', d.svc.fuel && 'fuel', d.tech && 'technical support', d.overnight && 'overnight'].filter(Boolean).join(', ')}</b></div>
    ${d.mayday ? `<div class="al cr" style="margin-top:8px;cursor:default"><b>MAYDAY</b> — the aircraft has landing priority and lands regardless of this decision. Assign stand & services; keep radio calls to the crew minimal.</div>` : ''}
    ${a.warn.length ? `<div class="al cr" style="margin-top:8px;cursor:default">${a.warn.join(' · ')}</div>` : ''}
    <div style="margin-top:8px"><b class="sm">Compatible stand options (for review)</b>${a.opts.map((o, i) => `<label class="row sm" style="margin-top:4px"><input type="radio" name="dvo-${d.id}" value="${i}" ${i == 0 ? 'checked' : ''}><b>${o.stand}</b> ${o.kind} · ${o.term} — ${o.note}</label>`).join('') || '<div class="mu sm">none projected free</div>'}</div>
    <div class="row" style="margin-top:10px"><button class="btn pri" onclick="decideDiv('${d.id}',1)">Accept (authorised)</button>${d.mayday ? `<span class="mu sm">Auto-assigns option 1 at ${loc(d.etaT - 6)} if no decision is made</span>` : `<button class="btn" onclick="decideDiv('${d.id}',0)">Refer to alternate</button>`}</div>
    <p class="note">Options show capacity & safety factors only. Estimated charges appear after acceptance and are not an input to the decision.</p></div>`}
  const r = S.rot[d.rot], L = r ? S.L.filter(e => e.rot == r.id) : [];
  return `<div class="card" style="margin-bottom:10px"><div class="ch"><span style="color:var(--tx);text-transform:none;font-size:13px">${d.fl} · ${d.type} · ${esc(d.reason)}</span><span class="sp"></span>${bd(d.status, d.status == 'ACCEPTED' ? 'vi' : '')}${r ? ' ' + bd(r.ph, phCls(r)) : ''}</div>
  <div class="g g2"><div><div class="tl">${d.log.map(([t, m]) => `<div><span class="mu">${loc(t)}</span> ${esc(m)}</div>`).join('')}</div>${r ? `<div class="row" style="margin-top:6px"><button class="btn" onclick="inspect('rot','${r.id}')">Open aircraft</button></div><p class="mu sm">Tasks: ${S.tasks.filter(k => k.r == r.id).map(k => k.kind + ' (' + k.st.toLowerCase() + ')').join(', ')}</p>` : ''}</div>
  <div>${L.length ? `<table><tr><th>Charge / cost</th><th class="n">USD</th><th>Status</th></tr>${L.map(e => `<tr title="${esc(e.formula)}"><td class="sm">${e.kind == 'rev' ? '' : '(cost) '}${esc(e.cat)}</td><td class="n">${money(e.usd)}</td><td>${bd(e.status)}</td></tr>`).join('')}</table>` : '<div class="mu sm">Charges post on landing / on-block.</div>'}
  <p class="note">Estimated charges, actual costs and uncertain recoveries are kept separate; treatment "${S.cfg.diversion.treatment}".</p></div></div></div>`}).join('') : '<div class="empty">No requests. Submit one, or inject “Emergency diversion request”.</div>';
function decideDiv(id, ok) {if (!can()) return; const d = S.div.find(x => x.id == id);
  if (ok) {const o = document.querySelector(`input[name="dvo-${id}"]:checked`); if (!confirm(`Accept ${d.fl} and reserve stand? (authorised personnel only)`)) return; const e = acceptDiversion(S, id, o ? +o.value : 0, role); e ? toast(e) : toast(d.fl + ' accepted')}
  else {declineDiversion(S, id, role); toast(d.fl + ' referred to alternate')} live(true)}
VIEWS['saf.inc'] = {sub: 'Occurrence reporting and investigation workflow.',
  html: () => `<div class="card"><div class="ch">Report occurrence</div><div class="row"><select id="ic">${['Bird strike', 'FOD', 'Fuel spill', 'Ground equipment damage', 'Near miss', 'Passenger medical', 'Runway incursion'].map(c => `<option>${c}</option>`).join('')}</select><select id="is"><option>Hazard</option><option>Near miss</option><option>Incident</option><option>Serious incident</option></select><input id="idsc" placeholder="Description (required)" style="flex:1;min-width:200px"><button class="btn pri" onclick="addInc()">Submit</button></div></div><div data-live="incList" style="margin-top:12px"></div>`};
const ISTEPS = ['Classified', 'Escalated', 'Root cause (5 Whys)', 'Corrective action', 'Closed'];
LIVE.incList = () => S.inc.map((x, i) => `<div class="card" style="margin-bottom:8px"><b>${x.id}</b> ${x.c} · ${x.s} · ${loc(x.t)} — ${esc(x.d)}<div class="row" style="margin-top:6px">${ISTEPS.map((n, j) => bd(n, j <= x.step ? 'ok' : '')).join('')}${x.step < 4 ? `<button class="btn" onclick="if(can()){S.inc[${i}].step++;ev(S,'IncidentEscalated','${x.id}','Step '+S.inc[${i}].step);audit('Incident ${x.id} advanced');live(true)}">Advance</button>` : ''}</div></div>`).join('') || '<div class="empty">No occurrences reported.</div>';
function addInc() {if (!can()) return; const d = $('#idsc').value.trim(); if (!d) return toast('Description is required'); const id = 'INC-' + pad(S.inc.length + 1); S.inc.unshift({id, c: $('#ic').value, s: $('#is').value, d, t: S.t, step: 0}); ev(S, 'IncidentReported', id, $('#ic').value); alrt(S, 'wn', 'Safety', $('#ic').value + ' reported', 'Initial classification and risk assessment', 'Safety investigator'); if ($('#ic').value == 'FOD') S.risks.push({t: S.t, k: 'FOD'}); $('#idsc').value = ''; live(true)}
VIEWS['saf.risk'] = {sub: 'Risk register derived from current simulated conditions (likelihood × severity, 5×5).', html: () => `<div class="g g2"><div class="card"><div class="ch">Risk matrix</div><div data-live="riskMx"></div></div><div class="card"><div class="ch">Active risks</div><div data-live="riskList"></div></div></div>`};
function risks() {const R = [];
  R.push(['Runway incursion during mixed-mode', mixed(S) ? 3 : 1, 5, mixed(S) ? 'Single-runway ops active' : 'Both runways open', 'ATC / airfield ops']);
  R.push(['Ramp lightning exposure', S.wx.light ? 4 : 1, 4, S.wx.light ? 'Thunderstorm active' : 'No CB activity', 'Ramp safety']);
  R.push(['Wildlife (bird) strike', S.risks.some(x => x.k == 'BIRD') ? 4 : 2, 4, S.risks.some(x => x.k == 'BIRD') ? 'Bird strike today — patrols intensified' : 'Patrols every 2 h', 'Wildlife control']);
  R.push(['FOD damage', S.wx.sand || S.risks.some(x => x.k == 'FOD') ? 4 : 2, 3, S.wx.sand ? 'Sandstorm' : 'Routine sweeps', 'Airfield ops']);
  R.push(['Stand conflict / ground collision', S.R.some(r => r.ph == 'AWAITING STAND') ? 4 : S.R.some(r => r.block) ? 3 : 2, 3, S.R.filter(r => r.block).length + ' constrained aircraft', 'Apron control']);
  R.push(['Dispatch with unresolved defect', S.defects.some(d => !/RELEASED/.test(d.status)) ? 2 : 1, 5, 'Controlled by CRS release gate', 'Maintenance control']);
  R.push(['Baggage security reconciliation', S.bhs.fault ? 3 : 1, 4, S.bhs.fault ? 'Manual sort in progress' : 'Automated', 'Baggage ops / security']);
  R.push(['Low-visibility taxi errors', S.wx.vis < 1.5 ? 4 : 1, 4, S.wx.vis < 1.5 ? 'LVP active' : 'Good visibility', 'ATC / pilots']);
  R.push(['Emergency response capacity', S.div.some(d => d.status == 'ACCEPTED' && S.rot[d.rot] && S.rot[d.rot].onBlk == null) ? 3 : 1, 5, 'ARFF availability ' + vehAvail(S, 'FT').length + '/2', 'ARFF']);
  return R}
LIVE.riskMx = () => {const R = risks(), c = 46; let s = `<svg viewBox="0 0 ${c * 5 + 40} ${c * 5 + 30}" style="width:100%;max-width:340px">`;
  for (let l = 1; l <= 5; l++) for (let v = 1; v <= 5; v++) {const sc = l * v; s += `<rect x="${30 + (v - 1) * c}" y="${(5 - l) * c}" width="${c - 2}" height="${c - 2}" rx="4" style="fill:var(${sc >= 15 ? '--rk-h' : sc >= 8 ? '--rk-m' : '--rk-l'})"/>`}
  R.forEach((r, i) => {s += `<circle cx="${30 + (r[2] - 1) * c + 12 + (i % 3) * 11}" cy="${(5 - r[1]) * c + 14 + Math.floor(i / 3) % 3 * 11}" r="5" style="fill:var(--tx)"><title>${esc(r[0])}</title></circle>`});
  return s + `<text x="${30 + c * 2.5}" y="${c * 5 + 20}" text-anchor="middle">Severity →</text><text x="10" y="${c * 2.5}" transform="rotate(-90 10 ${c * 2.5})" text-anchor="middle">Likelihood →</text></svg>`};
LIVE.riskList = () => `<table><tr><th>Risk</th><th class="n">L</th><th class="n">S</th><th>Rating</th><th>Driver</th><th>Owner</th></tr>${risks().sort((a, b) => b[1] * b[2] - a[1] * a[2]).map(r => {const sc = r[1] * r[2]; return `<tr><td>${r[0]}</td><td class="n">${r[1]}</td><td class="n">${r[2]}</td><td>${bd(sc >= 15 ? 'HIGH' : sc >= 8 ? 'MEDIUM' : 'LOW', sc >= 15 ? 'cr' : sc >= 8 ? 'wn' : 'ok')}</td><td class="mu sm">${r[3]}</td><td class="sm">${r[4]}</td></tr>`}).join('')}</table>`;
VIEWS['saf.reports'] = {sub: 'Operational KPIs (simulated definitions — not official airport performance), event log and exports.',
  html: () => `<div class="g g2"><div class="card"><div class="ch">Operational KPIs<span class="sp"></span><button class="btn" onclick="expEv()">Event log CSV</button><button class="btn" onclick="expLedger()">Ledger CSV</button></div><div data-live="kpiTab"></div></div><div class="card"><div class="ch">Average departure delay — actual vs baseline</div><div data-live="dlyChart"></div></div></div>
  <div class="card" style="margin-top:12px"><div class="ch">Event log</div><div data-live="evFull" class="tw" style="max-height:50vh"></div></div>`};
LIVE.kpiTab = () => {const k = kpi(S); return `<table>${[['Departures completed', k.dep], ['Arrivals on block', k.arr], ['On-time departures % (≤15 min)', k.ot], ['Average departure delay (min)', k.avg], ['Missed approaches', k.mad], ['Diverted away', k.div], ['Flights currently constrained', k.held], ['Mishandled bags', k.bagsMiss], ['Alerts raised', k.al], ['Energy kWh', kfmt(k.kwh)], ['Emissions tCO₂e', (k.co2 / 1000).toFixed(1)], ['Est. operating profit', money(k.op)]].map(([a, b]) => `<tr><td>${a}</td><td class="n"><b>${b}</b></td></tr>`).join('')}</table>`};
LIVE.dlyChart = () => lineChart('c-dly', [{name: 'Actual', color: 'var(--s2)', pts: S.snap.map(x => [x.t, x.dly])}, {name: 'Baseline', color: 'var(--mu)', pts: BASE.snap.filter(x => x.t <= S.t).map(x => [x.t, x.dly]), dash: 1}], {fx: loc, fy: v => v.toFixed(1) + ' min'});
LIVE.evFull = () => `<table><tr><th>Time</th><th>Event</th><th>Ref</th><th>Detail</th></tr>${S.ev.slice(0, 250).map(e => `<tr><td class="mu">${loc(e.t)}</td><td>${e.type}</td><td>${esc(e.f)}</td><td class="mu">${esc(e.msg)}</td></tr>`).join('')}</table>`;
function expEv() {dl('cai_sim_events.csv', 'sim_time,type,ref,message\n' + S.ev.map(e => [loc(e.t), e.type, e.f, '"' + String(e.msg).replace(/"/g, '""') + '"'].join(',')).join('\n'), 'text/csv')}
VIEWS['saf.tests'] = {sub: 'Automated scenario tests: each runs the full engine headless and checks cross-system effects.',
  html: () => `<div class="row" style="margin-bottom:12px"><button class="btn pri" onclick="runTests(true)">Run all tests</button><span class="mu sm">Load a scenario into the live simulation from the top-bar scenario menu (timed presets).</span></div><div id="testOut">${TESTRES ? testHTML(TESTRES) : '<div class="card empty">Not run yet.</div>'}</div>`};
VIEWS['saf.audit'] = {sub: 'Audit trail of user actions and data provenance.', html: () => `<div class="g g2"><div class="card"><div class="ch">Data categories</div><table><tr><td>${bd('Verified reference', 'ok')}</td><td style="white-space:normal">None marked verified. Runway designators, terminal names and layout are conceptual and must be checked against official CAI / ECAA / ICAO AIP sources.</td></tr><tr><td>${bd('Illustrative', 'wn')}</td><td style="white-space:normal">Schedule, registrations, stands, tariffs, costs, power ratings, fares, weather, images.</td></tr><tr><td>${bd('Simulated live', 'in')}</td><td style="white-space:normal">Everything the engine updates each tick (seed ${SEED}). No live ADS-B, AODB, BMS or meter feeds are connected.</td></tr></table></div><div class="card"><div class="ch">Audit log</div><div data-live="auditTab" class="tw" style="max-height:60vh"></div></div></div>`};
LIVE.auditTab = () => S.au.map(a => `<div class="sm">${loc(a.t)} · <b>${esc(a.role)}</b> · ${esc(a.m)}</div>`).join('') || '<div class="empty">Empty</div>';

// ---------- INSPECTORS ----------
const INSP = {};
INSP.rot = id => {const r = S.rot[id], T = AC_TYPES[r.type], ks = S.tasks.filter(k => k.r == r.id), bg = rbags(S, r.id).filter(b => b.r == r.id), bc = {}; for (const b of bg) bc[b.st] = (bc[b.st] || 0) + 1;
  const pk = r.onBlk != null ? parkingCalc(S, r, r.offBlk ?? S.t) : null, ov = r.onBlk != null && r.dep ? overstayCalc(S, r, r.offBlk ?? S.t) : null, L = S.L.filter(e => e.rot == r.id);
  return [`${fid(r)} <span class="mu sm">${r.al}</span>`, `<div class="row" style="margin-bottom:8px">${bd(r.ph, phCls(r))}${dispB(r)}<span class="tag">${r.op}</span><span class="tag">simulated</span></div>
  <div class="kv"><span>Aircraft</span><b>${r.type} · ${r.reg} · code ${T.code} · ${T.mtow} t · ${T.span} m</b>${r.arr ? `<span>Inbound</span><b>${r.arr.fl} from ${r.arr.apt} · STA ${loc(r.arr.sta)}${r.onBlk != null ? ' · on-block ' + (r.onBlk < 0 ? 'overnight' : loc(r.onBlk)) : r.diverted ? ' · DIVERTED' : ' · ETA ' + loc(r.eta + 7)}</b>` : ''}
  ${r.dep ? `<span>Outbound</span><b>${r.dep.fl} to ${r.dep.apt} · STD ${r.dep.std < DAY_END ? loc(r.dep.std) : 'next day'}${r.tobt != null && r.tobt < DAY_END ? ' · TOBT ' + loc(r.tobt) : ''}${r.offBlk != null ? ' · off-block ' + loc(r.offBlk) : ''}</b>` : ''}<span>Stand</span><b>${r.stand}${r.stand != r.planStand ? ' (planned ' + r.planStand + ')' : ''}</b><span>Passengers</span><b>${r.paxIn} in · ${r.paxOut} out</b><span>Constraint</span><b>${esc(r.block || 'none')}</b>
  <span>Flight plan</span><b class="sm">Route & waypoints: configurable placeholder · FL350 requested (illustrative) · simulated clearance only</b></div>
  ${Object.keys(r.dly).length ? `<h4>Delay attribution</h4><table>${Object.values(r.dly).map(d => `<tr><td class="sm" style="white-space:normal">${esc(d.label)}</td><td class="n">${d.min} min</td><td>${d.party}</td></tr>`).join('')}</table>` : ''}
  ${ks.length ? `<h4>Ground handling tasks</h4>${ks.map(k => `<div class="row sm"><span style="width:110px">${k.kind}</span>${bd(k.st, k.st == 'DONE' ? 'ok' : k.st == 'WAITING' ? 'wn' : 'in')}<span class="mu">${k.v || ''} ${k.te ? 'done ' + loc(k.te) : k.start > S.t ? 'from ' + loc(k.start) : ''}</span></div>`).join('')}` : ''}
  ${bg.length ? `<h4>Baggage (${bg.length})</h4><div class="row">${Object.entries(bc).map(([k, v]) => `<span class="tag">${k}: ${v}</span>`).join('')}</div><button class="btn" style="margin-top:6px" onclick="bagFl='${r.id}';go('bag','track')">List bags</button>` : ''}
  ${pk ? `<h4>Stand charges ${r.offBlk == null ? '(provisional, accruing)' : ''}</h4><div class="kv"><span>Parking</span><b>${money(pk.usd)}</b><span></span><b class="formula">${esc(pk.formula)}</b>${ov && ov.blocks ? `<span>Overstay</span><b>${money(ov.usd)} · ${ov.status}${ov.why ? ' — ' + esc(ov.why) : ''} · payer ${ov.payer}</b><span></span><b class="formula">${esc(ov.formula)}</b>` : ''}</div>` : ''}
  ${L.length ? `<h4>Ledger entries</h4><table>${L.map(e => `<tr title="${esc(e.formula)}"><td class="sm">${esc(e.cat)}</td><td class="n">${money(e.usd)}</td><td>${bd(e.status)}</td></tr>`).join('')}</table>` : ''}
  <h4>Actions</h4><div class="row">${r.dep && r.offBlk == null ? `<button class="btn" onclick="doDefect('${r.id}')">Report defect</button><button class="btn" onclick="if(can()){scn(S,'overstay',role,'${r.id}');live(true)}">Operator hold +70 min</button>` : ''}${r.mx ? `<button class="btn" onclick="inspect('def','${r.mx}')">Open work order</button>` : ''}<button class="btn" onclick="inspect('stand','${r.stand}')">Stand ${r.stand}</button></div>
  <h4>Event history</h4><div class="tl">${S.ev.filter(e => e.f == fid(r) || e.f == (r.arr && r.arr.fl) || e.f == (r.dep && r.dep.fl)).slice(0, 14).map(e => `<div><span class="mu">${loc(e.t)}</span> ${esc(e.msg)}</div>`).join('')}</div>`]};
INSP.park = id => {const r = S.rot[id], T = AC_TYPES[r.type], end = r.offBlk ?? S.t, pk = parkingCalc(S, r, end), ov = r.dep ? overstayCalc(S, r, end) : null, base = r.allowedOff != null ? parkingCalc(S, r, Math.min(end, r.allowedOff)) : pk;
  const extraMin = r.allowedOff != null ? Math.max(0, end - r.allowedOff) : 0, gpuE = extraMin / 60 * S.cfg.gpuKw * S.cfg.elec.peakEgp / S.cfg.fx, pbb = STAND[r.stand].kind == 'contact' ? extraMin / 60 * S.cfg.pbbUsdHr : 0, opp = S.opp.filter(o => o.blocker == r.id).reduce((a, o) => a + o.usd, 0), conc = Math.min(S.cfg.concession.capMin, extraMin) * r.paxOut * S.cfg.concession.delayUpliftUsdPerMin;
  return [`Stand occupancy · ${fid(r)}`, `<div class="kv"><span>Aircraft</span><b>${r.type} ${T.code} · ${T.mtow} t · ${r.reg}</b><span>Stand</span><b>${r.stand}</b><span>Operation</span><b>${r.op}</b><span>Parking start</span><b>${r.onBlk < 0 ? 'overnight' : loc(r.onBlk)}</b><span>Allowed off-block</span><b>${r.allowedOff != null && r.allowedOff < DAY_END ? loc(r.allowedOff) : '—'}</b><span>Stand release</span><b>${r.offBlk != null ? loc(r.offBlk) : 'on stand (provisional)'}</b><span>Extra time on stand</span><b>${Math.round(extraMin)} min</b><span>Responsible</span><b>${ov ? ov.party + ' — ' + esc(ov.reason) : '—'}</b></div>
  <h4>Financial impact of the longer stand occupancy</h4><table><tr><th>Item</th><th class="n">USD</th><th>Who pays → receives</th></tr>
  <tr><td>Additional parking charge</td><td class="n">${money(pk.usd - base.usd)}</td><td>Airline → Airport</td></tr><tr><td>Overstay / stand-blocking charge</td><td class="n">${ov && ov.blocks ? money(ov.usd) : '—'}</td><td>${ov && ov.blocks ? (ov.status == 'waived' ? 'waived: ' + esc(ov.why) : ov.payer + ' → Airport') : ''}</td></tr>
  <tr><td>Additional boarding-bridge time</td><td class="n">${money(pbb)}</td><td>Airline → Airport</td></tr><tr><td>Concession dwell uplift (assumption)</td><td class="n">${money(conc)}</td><td>Concessionaires → Airport</td></tr>
  <tr><td>Airport cost: 400 Hz energy for extra time</td><td class="n neg">−${money(gpuE)}</td><td>Airport</td></tr><tr><td>Opportunity cost: other flights displaced</td><td class="n neg">${opp ? '−' + money(opp) : '—'}</td><td>Memo (economic, not booked)</td></tr>
  <tr><td>Airline delay cost</td><td class="n">${r.dep ? money(Math.max(0, end - r.dep.std) * T.dcost) : '—'}</td><td>Airline (own cost)</td></tr></table>
  <p class="note">A late departure does not automatically mean extra airport profit — exemptions, waivers, disputes and displaced traffic can offset or cancel the charge.</p>
  ${ov && ov.blocks && r.offBlk == null ? `<label class="row sm" style="margin-top:8px"><input type="checkbox" ${r.disputeOverstay ? 'checked' : ''} onchange="if(can()){S.rot['${r.id}'].disputeOverstay=this.checked;audit('Overstay dispute flag ${fid(r)}: '+this.checked)}">Operator disputes overstay (post as disputed)</label>` : ''}`]};
INSP.stand = id => {const s = STAND[id], o = S.rot[S.stOcc[id]], nx = S.R.filter(r => r.stand == id && r.onBlk == null && r.arr && !r.diverted).sort((a, b) => a.eta - b.eta);
  return [`Stand ${id}`, `<div class="kv"><span>Area</span><b>${s.term} · ${s.kind}</b><span>Max aircraft</span><b>code ${s.max}</b><span>Boarding bridge</span><b>${s.kind == 'contact' ? 'yes + fixed 400 Hz' : 'no — bus & mobile GPU'}</b><span>Occupant</span><b>${o ? `<a href="#" style="color:var(--ac)" onclick="inspect('rot','${o.id}');return false">${fid(o)}</a> since ${o.onBlk < 0 ? 'overnight' : loc(o.onBlk)}` : 'free'}</b>${S.stRes[id] ? `<span>Reserved</span><b>${fid(S.rot[S.stRes[id]])} (emergency)</b>` : ''}</div>
  <h4>Upcoming</h4>${nx.map(r => `<div class="row sm" style="cursor:pointer" onclick="inspect('rot','${r.id}')"><b>${fid(r)}</b> ETA ${loc(r.eta + 7)} ${r.type}</div>`).join('') || '<div class="mu sm">none planned</div>'}${o ? `<button class="btn" style="margin-top:8px" onclick="inspect('park','${o.id}')">Charges & overstay impact</button>` : ''}`]};
INSP.veh = id => {const v = S.V.find(x => x.id == id), k = v.task && S.tasks.find(x => x.id == v.task);
  return [`${v.id} · ${VNAME[v.type]}`, `<div class="kv"><span>Status</span><b>${v.down ? 'OUT OF SERVICE' : v.st}${v.sus ? ' (lightning stop)' : ''}</b><span>Owner</span><b>${v.owner == 'GH' ? 'Ground handler' + (S.cfg.handler == 'airport' ? ' (airport-owned)' : '') : v.owner}</b><span>Power</span><b>${v.ev ? 'electric' : 'diesel'}</b><span>Current task</span><b>${k ? k.kind + ' · ' + fid(S.rot[k.r]) + ' @ ' + S.rot[k.r].stand : '—'}</b><span>ETA</span><b>${v.mv && !mvDone(S, v.mv) ? loc(v.mv.t0 + v.mv.dur) : '—'}</b>
  <span>Distance today</span><b>${v.km.toFixed(1)} km</b><span>Energy today</span><b>${v.ev ? v.kwh.toFixed(1) + ' kWh' : v.L.toFixed(1) + ' L diesel'}</b><span>Working time</span><b>${v.workMin} min</b><span>Restrictions</span><b>${S.wx.light ? 'Lightning: ramp suspended' : S.wx.vis < 1.5 ? 'LVP: speed −40%' : 'none'}</b></div>
  <h4>Task history</h4>${S.tasks.filter(t => t.v == v.id).slice(-8).reverse().map(t => `<div class="sm">${t.kind} · ${fid(S.rot[t.r])} · ${t.st}${t.te ? ' ' + loc(t.te) : ''}</div>`).join('') || '<div class="mu sm">none</div>'}<div class="row" style="margin-top:8px"><button class="btn" onclick="vehToggle('${v.id}')">${v.down ? 'Return to service' : 'Take out of service'}</button></div>`]};
INSP.zone = id => {const z = ZONE[id], T = TERMS.includes(id), kwh = S.en.kwhT[id] ? Object.entries(S.en.kwhT[id]) : [];
  return [z.name, `${TIMG[id] ? `<div style="height:150px;border-radius:8px;background:url(${IMG[TIMG[id]]}) center/cover;margin-bottom:8px"></div><span class="tag">illustrative image</span>` : ''}<div class="kv" style="margin-top:8px">${T ? `<span>Passengers now</span><b>${Math.round(S.occ[id] || 0)}</b><span>Security queue est.</span><b>${queueMin(id)} min</b>` : ''}${id == 'BHS' ? `<span>Sorter</span><b>${S.bhs.fault ? 'FAULT' : 'running'}</b><span>Bags in system</span><b>${S.Bact.length}</b>` : ''}${id == 'CUP' ? `<span>Chillers</span><b>${S.spike ? 'control fault (T3 spike)' : 'normal'}</b>` : ''}${id == 'TWR' ? `<span>Positions</span><b>TWR · GND · APP (training sim)</b>` : ''}${id == 'ARFF' ? `<span>Fire tenders available</span><b>${vehAvail(S, 'FT').length}/2</b>` : ''}</div>
  ${kwh.length ? `<h4>Energy today</h4><table>${kwh.map(([k, v]) => `<tr><td>${ENCATS[k]}</td><td class="n">${kfmt(v)} kWh</td></tr>`).join('')}</table>` : ''}<div class="row" style="margin-top:8px">${T ? `<button class="btn" onclick="go('ops','terms')">Terminals</button>` : ''}${id == 'BHS' ? `<button class="btn" onclick="go('bag','flow')">Baggage flow</button>` : ''}${id == 'CUP' ? `<button class="btn" onclick="go('biz','energy')">Energy</button>` : ''}${id == 'TWR' ? `<button class="btn" onclick="go('ops','atc')">ATC sim</button>` : ''}</div>`]};
INSP.rwy = n => [`RWY ${n} (conceptual)`, `<div class="kv"><span>Status</span><b>${S.rw[n].open ? 'OPEN' : 'CLOSED'}</b><span>Use</span><b>${n == 1 ? 'Arrivals' : 'Departures'}${mixed(S) ? ' (mixed-mode)' : ''}</b><span>Spacing</span><b>arr ${arrSpacing(S)} · dep ${depSpacing(S)} min</b></div><p class="note">Designators and geometry are conceptual, pending verification against the AIP.</p><div class="row"><button class="btn" onclick="go('ops','airfield')">Airfield</button></div>`];
INSP.bag = id => {const b = S.B.find(x => x.id == id); if (!b) return ['Bag', 'Not found']; const r = S.rot[b.r];
  return [`Bag ${b.id}`, `<div style="text-align:center">${qr(b.id + b.px)}<div class="mu sm">QR mock-up (decorative pattern, not a standards-compliant code)</div></div>
  <div class="kv" style="margin-top:8px"><span>Passenger ref</span><b>${b.px} (pseudonymous)</b><span>Flight</span><b>${b.fl}${b.fromR ? ' (transfer from ' + fid(S.rot[b.fromR]) + ')' : b.tr ? ' → connecting ' + b.trFl : ''}</b><span>Status</span><b>${b.st}</b>${!b.arr ? `<span>Make-up</span><b>${chuteOf(b.r) + 1}</b>` : b.car ? `<span>Reclaim</span><b>${b.car}</b>` : ''}<span>Aircraft</span><b>${r.reg} @ ${r.stand} · ${r.ph}</b></div>
  <h4>Scan history</h4><div class="tl">${b.sc.map(([t, s]) => `<div><span class="mu">${loc(t)}</span> ${s}</div>`).join('')}</div><p class="note">No personal data shown. Production QR tokens must be unguessable and access-controlled.</p>`]};
INSP.def = id => {const d = S.defects.find(x => x.id == id), r = S.rot[d.r], im = defectImpact(S, d);
  return [`${d.wo} · ${d.ata}`, `<div class="row">${bd(d.sev, d.sev == 'NO-GO' ? 'cr' : 'wn')}${bd(d.status)}</div><div class="kv" style="margin-top:8px"><span>Defect</span><b>${d.name}</b><span>Aircraft</span><b>${r.reg} ${r.type} · ${fid(r)}</b><span>Dispatch</span><b>${d.sev == 'NO-GO' ? 'Not dispatch-ready until CRS' : d.mel}</b><span>Est. ready</span><b>${loc(d.estReady)}</b><span>Direct cost</span><b>${money(im.direct)}</b><span>Net impact</span><b>${money(im.net)}</b></div>
  <div class="tl" style="margin-top:8px">${d.log.map(([t, m]) => `<div><span class="mu">${loc(t)}</span> ${esc(m)}</div>`).join('')}</div><div class="row" style="margin-top:8px"><button class="btn pri" ${d.status != 'AWAITING RELEASE' ? 'disabled' : ''} onclick="doRelease('${d.id}')">Sign CRS</button><button class="btn" onclick="go('ast','wo')">Work orders</button></div>`]};
INSP.alert = id => {const a = S.al.find(x => x.id == id); if (!a) return ['Alert', '']; const R = a.ref;
  return [`${a.sys} alert`, `<div class="row">${sevB(a)}<span class="mu">${loc(a.t)} · ${a.id}</span></div><p style="font-size:14px">${esc(a.msg)}</p><div class="kv"><span>Recommended</span><b style="white-space:normal">${esc(a.rec)}</b><span>Owner</span><b>${esc(a.owner)}</b></div>
  <div class="row" style="margin-top:10px">${a.res ? bd('RESOLVED', 'ok') : `<button class="btn pri" onclick="if(can()){S.al.find(x=>x.id=='${a.id}').res=1;audit('Resolved ${a.id}');live(true)}">Acknowledge / resolve</button>`}${R && INSP[R.k] ? `<button class="btn" onclick="inspect('${R.k}',${typeof R.id == 'number' ? R.id : `'${R.id}'`})">Open related object</button>` : ''}${R && R.k == 'ledger' ? `<button class="btn" onclick="go('biz','pnl')">Financial P&L</button>` : ''}${R && R.k == 'div' ? `<button class="btn" onclick="go('saf','emerg')">Diversion workflow</button>` : ''}</div>`]};
INSP.div = id => {const d = S.div.find(x => x.id == id); return [`Diversion ${d.fl}`, `<div class="kv"><span>Status</span><b>${d.status}</b><span>Reason</span><b>${esc(d.reason)}</b><span>ETA</span><b>${loc(d.etaT)}</b><span>Stand</span><b>${d.stand || '—'}</b></div><div class="tl" style="margin-top:8px">${d.log.map(([t, m]) => `<div><span class="mu">${loc(t)}</span> ${esc(m)}</div>`).join('')}</div><button class="btn" style="margin-top:8px" onclick="go('saf','emerg')">Open workflow</button>`]};
